he January 1979 \\\"Treasury Bulletin.\\\"\", \"description\": null, \"id\": 6, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1058, 189, 1495, 467], \"page_id\": 67}], \"content\": \"SPECIAL REPORTS Trust Funds\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [714, 94, 916, 130], \"page_id\": 68}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1455, 94, 1494, 127], \"page_id\": 68}], \"content\": \"67\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [550, 193, 1089, 233], \"page_id\": 68}], \"content\": \"TABLE TF-6A.\\u2014Highway Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 245, 801, 436], \"page_id\": 68}], \"content\": \"The following information is released according to the provisions of the Byrd Amendment [codified at 26 United States Code 9503(d)] and represents data concerning the Highway Trust Fund. The figure described as \\\"unfunded authorizations\\\" is the latest estimate received from the DOT for fiscal year 2013.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 243, 1494, 434], \"page_id\": 68}], \"content\": \"The 48-month revenue estimates for the highway and mass transit accounts, respectively, include the latest estimates received from Treasury's Office of Tax Analysis for excise taxes, net of refunds. They represent net highway receipts for those periods beginning at the close of fiscal year 2013.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [694, 512, 949, 554], \"page_id\": 68}], \"content\": \"Highway Account\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [696, 556, 949, 587], \"page_id\": 68}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\":