box\": [{\"coord\": [138, 1120, 1488, 1183], \"page_id\": 69}], \"content\": \"9303. \\\"Distributional Effects of Social Security: The Notch Issue Revisited.\\\" James E. Duggan, Robert Gillingham, and John S. Greenlees. Revised April 1995.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1207, 1488, 1270], \"page_id\": 69}], \"content\": \"9501. \\\"Progressive Returns to Social Security? An Answer from Social Security Records.\\\" James E. Duggan, Robert Gillingham, and John S. Greenlees. November 1995.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1296, 1488, 1358], \"page_id\": 69}], \"content\": \"9701. \\u201cHousing Bias in the CPI and Its Effects on the Budget Deficit and Social Security Trust Fund.\\u201d James E. Duggan, Robert Gillingham, and John S. Greenlees. January 1997.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1384, 1488, 1447], \"page_id\": 69}], \"content\": \"9702. \\\"An Improved Method for Estimating the Total Taxable Resources of the States.\\\" Michael Compson and John Navratil. December 1997.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1471, 1488, 1534], \"page_id\": 69}], \"content\": \"2001-01. \\\"Some Regulatory and Institutional Barriers to Congestion Pricing at Airports.\\\" Edward Murphy and John D. Worth. May 2001.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1560, 1364, 1622], \"page_id\": 69}], \"content\": \"2001-02. \\\"Actuarial Nonequivalence in Early and Delayed Social Security Benefit Claims.\\\" James E. Duggan and Christopher J. Soares. June 2001.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1987, 246, 2018], \"page_id\": 69}], \"content\": \"June 2014\", \"description\": null, \"id\": 19, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [636, 92, 1000, 127], \"page_id\": 70}], \"content\": \"RESEARCH PAPER SERIES\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1455, 94, 1494, 130], \"page_id\": 70}], \"content\": \"69\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [137, 186, 1426, 257], \"page_id\": 70}], \"content\": \"2003-01. \\u201cAnnuity Risk: Volatility and Inflation Exposure in Payments from Immediate Life Annuities.\\u201d Christopher J. Soares and Mark Warshawsky. January 2003.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 273, 1481, 342], \"page_id\": 70}], \"content\": \"2005-01. \\u201cPossible Alternatives to the Medicare Trustees\\u2019 Long-Term Projections of Health Spending.\\u201d Jason D. Brown and Ralph M. Monaco. January 2005.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 363, 1186, 405], \"page_id\": 70}], \"content\": \"2005-02. \\u201cThe Long-Term Real Interest Rate for Social Security.\\u201d James A. Girola. March 2005.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [131, 420, 1464, 490], \"page_id\": 70}], \"content\": \"2006-01. \\\"Implications of Returns on Treasury Inflation-Indexed Securities for Projections of the Long-Term Real Interest Rate.\\\" James A. Girola. March 2006.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 512, 1494, 582], \"page_id\": 70}], \"content\": \"2007-01. \\\"Mortality and Lifetime Income Evidence from Social Security Records.\\\" James E. Duggan, Robert Gillingham, and John S. Greenlees. December 2006.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [131, 596, 1417, 669], \"page_id\": 70}], \"content\": \"2007-02. \\u201cThe Impact of Post-9/11 Visa Policies on Travel to the United States.\\u201d Brent Neiman and Phillip L. Swagel. June 2007.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [131, 686, 1472, 759], \"page_id\": 70}], \"content\": \"2008-01. \\u201cPrefunding Social Security Benefits to Achieve Intergenerational Fairness: Can It Be Done in the Social Security Trust Fund?\\u201d Randall P. Mariger. December 2008.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [131, 773, 1490, 842], \"page_id\": 70}], \"content\": \"2008-02. \\u201cDo Social Security Surpluses Pay Down Publicly Held Debt? Evidence from Budget Data.\\u201d Randall P. Mariger. December 2008.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [559, 1740, 1066, 1893], \"page_id\": 70}], \"content\": \"Copies may be obtained by writing to: Ann Bailey, Department of the Treasury 1500 Pennsylvania Ave., NW., Room 4409 MT Washington, DC 20220 Telephone (202) 622-1519 or fax (202) 622-4112\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1381, 1985, 1497, 2015], \"page_id\": 70}], \"content\": \"June 2014\", \"description\": null, \"id\": 11, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [137, 92, 186, 134], \"page_id\": 71}], \"content\": \"70\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [426, 212, 1209, 304], \"page_id\": 71}], \"content\": \"Glossary With References to Applicable Sections and Tables\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [641, 321, 993, 344], \"page_id\": 71}], \"content\": \"Source: Bureau of the Fiscal Service\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 394, 805, 549], \"page_id\": 71}], \"content\": \"Amounts outstanding and in circulation (USC)\\u2014Includes all issues by the Bureau of the Mint purposely intended as a medium of exchange. Coins sold by the Bureau of the Mint at premium prices are excluded; however, uncirculated coin sets sold at face value plus handling charge are included.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 563, 801, 686], \"page_id\": 71}], \"content\": \"Average discount rate (PDO-1, -2)\\u2014In Treasury bill auctions, purchasers tender competitive bids on a discount rate basis. The average discount rate is the weighted, or adjusted, average of all bids accepted in the auction.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 700, 805, 915], \"page_id\": 71}], \"content\": \"Budget authority (\\\"Federal Fiscal Operations\\\")\\u2014Congress passes laws giving budget authority to Government entities, which gives the agencies the power to spend Federal funds. Congress can stipulate various criteria for the spending of these funds. For example, Congress can stipulate that a given agency must spend within a specific year, number of years, or any time in the future.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 931, 801, 1240], \"page_id\": 71}], \"content\": \"The basic forms of budget authority are appropriations, authority to borrow, contract authority, and authority to obligate and expend offsetting receipts and collections. The period of time during which Congress makes funds available may be specified as 1-year, multiple-year, or no-year. The available amount may be classified as either definite or indefinite; a specific amount or an unspecified amount can be made available. Authority also may be classified as current or permanent. Permanent authority requires no current action by Congress.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1256, 801, 1315], \"page_id\": 71}], \"content\": \"Budget deficit\\u2014The total, cumulative amount by which budget outlays (spending) exceed budget receipts (income).\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1329, 800, 1487], \"page_id\": 71}], \"content\": \"Cash management bills (PDO-1)\\u2014Marketable Treasury bills of irregular maturity lengths, sold periodically to fund short-term cash needs of Treasury. Their sale, having higher minimum and multiple purchase requirements than those of other issues, is generally restricted to competitive bidders.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1502, 801, 1655], \"page_id\": 71}], \"content\": \"Competitive tenders (\\u201cTreasury Financing Operations\\u201d)\\u2014A bid to purchase a stated amount of one issue of Treasury securities at a specified yield or discount. The bid is accepted if it is within the range accepted in the auction. (See Noncompetitive tenders.)\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1669, 800, 1766], \"page_id\": 71}], \"content\": \"Currency no longer issued (USCC)\\u2014Old and new series gold and silver certificates, Federal Reserve notes, national bank notes, and 1890 Series Treasury notes.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1777, 801, 1872], \"page_id\": 71}], \"content\": \"Debt outstanding subject to limitation (FD-6)\\u2014The debt incurred by the Treasury subject to the statutory limit set by Congress. Until World War I, a specific amount of debt was\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 394, 1494, 516], \"page_id\": 71}], \"content\": \"authorized to each separate security issue. Beginning with the Second Liberty Loan Act of 1917, the nature of the limitation was modified until, in 1941, it developed into an overall limit on the outstanding Federal debt.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [836, 530, 1494, 655], \"page_id\": 71}], \"content\": \"Pursuant to 31 U.S.C. 3101(b): By the Temporary Debt Limit Extension Act, Public Law 113-83, the Statutory Debt Limit has been suspended for the period February 15, 2014, through March 15, 2015.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 672, 1492, 733], \"page_id\": 71}], \"content\": \"Discount\\u2014The interest deducted in advance when purchasing notes or bonds. (See Accrued discount.)\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 745, 1494, 903], \"page_id\": 71}], \"content\": \"Discount rate (PDO-1)\\u2014The difference between par value and the actual purchase price paid, annualized over a 360-day year. Because this rate is less than the actual yield (coupon-equivalent rate), the yield should be used in any comparison with coupon issue securities.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 915, 1490, 976], \"page_id\": 71}], \"content\": \"Dollar coins (USCC)\\u2014Include standard silver and nonsilver coins.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 995, 1494, 1148], \"page_id\": 71}], \"content\": \"Domestic series (FD-2)\\u2014Nonmarketable, interest- and non-interest-bearing securities issued periodically by Treasury to the Resolution Funding Corporation (RFC) for investment of funds authorized under section 21B of the Federal Home Loan Bank Act (12 United States Code 1441b).\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1164, 1494, 1287], \"page_id\": 71}], \"content\": \"Federal intrafund transactions (\\u201cFederal Fiscal Operations\\u201d)\\u2014Intrabudgetary transactions in which payments and receipts both occur within the same Federal fund group (Federal funds or trust funds).\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1304, 1494, 1518], \"page_id\": 71}], \"content\": \"Federal Reserve notes (USCC)\\u2014Issues by the U.S. Government to the public through the Federal Reserve banks and their member banks. They represent money owed by the Government to the public. Currently, the item \\u201cFederal Reserve notes\\u2014amounts outstanding\\u201d consists of new series issues. The Federal Reserve note is the only class of currency currently issued.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1532, 1495, 1780], \"page_id\": 71}], \"content\": \"Foreign-targeted issue (PDO-2)\\u2014Foreign-targeted issues were notes sold between October 1984 and February 1986 to foreign institutions, foreign branches of U.S. institutions, foreign central banks or monetary authorities, or to international organizations in which the United States held membership. Sold as companion issues, they could be converted to domestic (normal) Treasury notes with the same maturity and interest rates. Interest was paid annually.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1794, 1490, 1857], \"page_id\": 71}], \"content\": \"Fractional coins (USCC)\\u2014Coins minted in denominations of 50, 25, and 10 cents, and minor coins (5 cents and 1 cent).\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1987, 253, 2018], \"page_id\": 71}], \"content\": \"June 2014\", \"description\": null, \"id\": 22, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [741, 97, 900, 132], \"page_id\": 72}], \"content\": \"GLOSSARY\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1457, 94, 1495, 130], \"page_id\": 72}], \"content\": \"71\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [137, 191, 803, 561], \"page_id\": 72}], \"content\": \"Government account series (FD-2)\\u2014Certain trust fund statutes require the Secretary of the Treasury to apply monies held by these funds toward the issuance of nonmarketable special securities. These securities are sold directly by Treasury to a specific Government agency, trust fund, or account. Their rate is based on an average of market yields on outstanding Treasury obligations, and they may be redeemed at the option of the holder. Roughly 80 percent of these are issued to five holders: the Federal Old-Age and Survivors Insurance Trust Fund; the civil service retirement and disability fund; the Federal Hospital Insurance Trust Fund; the military retirement fund; and the Unemployment Trust Fund.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 573, 803, 702], \"page_id\": 72}], \"content\": \"Interfund transactions (\\\"Federal Fiscal Operations\\\")\\u2014Transactions in which payments are made from one fund group (either Federal funds or trust funds) to a receipt account in another group.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 714, 801, 872], \"page_id\": 72}], \"content\": \"International Monetary Fund transactions (\\\"Exchange Stabilization Fund\\\", ESF-1)\\u2014(IMF) Established by the United Nations, the IMF promotes international trade, stability of exchange, and monetary cooperation. Members are allowed to draw from the fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 882, 803, 1040], \"page_id\": 72}], \"content\": \"Intrabudgetary transactions (\\\"Federal Fiscal Operations\\\")\\u2014These occur when payment and receipt both occur within the budget, or when payment is made from off-budget Federal entities whose budget authority and outlays are excluded from the budget totals.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1051, 803, 1179], \"page_id\": 72}], \"content\": \"Noncompetitive tenders (\\\"Treasury Financing Operations\\\")\\u2014This is a tender or bid to purchase a stated par amount of securities at the highest yield or discount rate awarded to competitive bidders for a single-price auction.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1190, 801, 1256], \"page_id\": 72}], \"content\": \"Obligations (\\\"Federal Fiscal Operations\\\")\\u2014An unpaid commitment to acquire goods or services.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1268, 800, 1454], \"page_id\": 72}], \"content\": \"Off-budget Federal entities (\\u201cFederal Fiscal Operations\\u201d)\\u2014 Federally owned and controlled entities whose transactions are excluded from the budget totals under provisions of law. Their receipts, outlays, and surplus or deficit are not included in budget receipts, outlays, or deficits. Their budget authority is not included in totals of the budget.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1466, 803, 1565], \"page_id\": 72}], \"content\": \"Outlays (\\\"Federal Fiscal Operations\\\")\\u2014Payments on obligations in the form of cash, checks, the issuance of bonds or notes, or the maturing of interest coupons.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1575, 801, 1641], \"page_id\": 72}], \"content\": \"Par value\\u2014The face value of bonds or notes, including interest.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1650, 807, 1902], \"page_id\": 72}], \"content\": \"Quarterly financing (\\u201cTreasury Financing Operations\\u201d)\\u2014Treasury has historically offered packages of several \\u201ccoupon\\u201d security issues on the 15th of February, May, August, and November, or on the next working day. These issues currently consist of a 3-year note, a 10-year note, and a 30-year bond. Treasury sometimes offers additional amounts of outstanding long-term notes or bonds, rather than selling new security issues. (See Reopening.)\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 189, 1494, 314], \"page_id\": 72}], \"content\": \"Receipts (\\\"Federal Fiscal Operations\\\")\\u2014Funds collected from selling land, capital, or services, as well as collections from the public (budget receipts), such as taxes, fines, duties, and fees.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 330, 1495, 457], \"page_id\": 72}], \"content\": \"Reopening (PDO-2)\\u2014The offer for sale of additional amounts of outstanding issues, rather than an entirely new issue. A reopened issue will always have the same maturity date, CUSIP-number, and interest rate as the original issue.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 467, 1494, 622], \"page_id\": 72}], \"content\": \"Special drawing rights (\\u201cExchange Stabilization Fund,\\u201d ESF-1)\\u2014International assets created by IMF that serve to increase international liquidity and provide additional international reserves. SDRs may be purchased and sold among eligible holders through IMF. (See IMF.)\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 632, 1495, 823], \"page_id\": 72}], \"content\": \"SDR allocations are the counterpart to SDRs issued by IMF based on members' quotas in IMF. Although shown in Exchange Stabilization Fund (ESF) statements as liabilities, they must be redeemed by ESF only in the event of liquidation of, or U.S. withdrawal from, the SDR department of IMF or cancellation of SDRs.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 837, 1495, 966], \"page_id\": 72}], \"content\": \"SDR certificates are issued to the Federal Reserve System against SDRs when SDRs are legalized as money. Proceeds of monetization are deposited into an ESF account at the Federal Reserve Bank of New York.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 976, 1494, 1044], \"page_id\": 72}], \"content\": \"Spot (\\u201cForeign Currency Positions\\u201d)\\u2014Due for receipt or delivery within 2 workdays.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1054, 1494, 1365], \"page_id\": 72}], \"content\": \"State and local government series (SLGS) (FD-2)\\u2014Special nonmarketable certificates, notes, and bonds offered to State and local governments as a means to invest proceeds from their own tax-exempt financing. Interest rates and maturities comply with IRS arbitrage provisions. SLGS are offered in both time deposit and demand deposit forms. Time deposit certificates have maturities of up to 1 year. Notes mature in 1 to 10 years and bonds mature in more than 10 years. Demand deposit securities are 1-day certificates rolled over with a rate adjustment daily.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1374, 1495, 1596], \"page_id\": 72}], \"content\": \"Statutory debt limit (FD-6)\\u2014By Act of Congress there is a limit, either temporary or permanent, on the amount of public debt that may be outstanding. When this limit is reached, Treasury may not sell new debt issues until Congress increases or extends the limit. For a detailed listing of changes in the limit since 1941, see the Budget of the United States Government. (See debt outstanding subject to limitation.)\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1605, 1495, 1827], \"page_id\": 72}], \"content\": \"STRIPS (PDO-2)\\u2014Separate Trading of Registered Interest and Principal Securities. Long-term notes and bonds may be divided into principal and interest-paying components, which may be transferred and sold in amounts as small as $1,000. STRIPS are sold at auction at a minimum par amount, varying for each issue. The amount is an arithmetic function of the issue's interest rate.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1382, 1987, 1494, 2018], \"page_id\": 72}], \"content\": \"June 2014\", \"description\": null, \"id\": 21, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 99, 173, 125], \"page_id\": 73}], \"content\": \"72\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [741, 97, 889, 125], \"page_id\": 73}], \"content\": \"GLOSSARY\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [138, 191, 800, 285], \"page_id\": 73}], \"content\": \"Treasury bills\\u2014The shortest term Federal security (maturity dates normally varying from 3 to 12 months), are sold at a discount.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 302, 800, 396], \"page_id\": 73}], \"content\": \"Trust fund transaction (\\u201cFederal Fiscal Operations\\u201d)\\u2014An intrabudgetary transaction in which both payments and receipts occur within the same trust fund group.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 191, 1488, 316], \"page_id\": 73}], \"content\": \"United States\\u2014Includes the 50 States, District of Columbia, Commonwealth of Puerto Rico, American Samoa, Midway Island, Virgin Islands, Wake Island, and all other territories and possessions.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 332, 1488, 424], \"page_id\": 73}], \"content\": \"U.S. notes (USCC)\\u2014Legal tender notes of five different issues: 1862 ($5-$1,000 notes); 1862 ($1-$2 notes); 1863 ($5-$1,000 notes); 1863 ($1-$10,000 notes); and 1901 ($10 notes).\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1989, 246, 2015], \"page_id\": 73}], \"content\": \"June 2014\", \"description\": null, \"id\": 6, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [95, 92, 362, 189], \"page_id\": 74}], \"content\": \"G20\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [372, 87, 672, 193], \"page_id\": 74}], \"content\": \"U.S. GOVERNMENT PRINTING OFFICE KEEPING AMERICA INFORMED\", \"descripti