{\"coord\": [1366, 1982, 1499, 2025], \"page_id\": 106}], \"content\": \"March 2014\", \"description\": null, \"id\": 10, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [137, 94, 197, 130], \"page_id\": 107}], \"content\": \"104\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [716, 92, 914, 130], \"page_id\": 107}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [412, 207, 1222, 255], \"page_id\": 107}], \"content\": \"INTRODUCTION: Oil Spill Liability Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [135, 266, 805, 639], \"page_id\": 107}], \"content\": \"The Oil Spill Liability Trust Fund was established on the books of the Treasury by section 8033 of the Omnibus Budget Reconciliation Act of 1986 (Public Law 99-509). It was made effective on January 1, 1990, by section 7811(m)(3) of the Omnibus Budget Reconciliation Act of 1989 (Public Law 101-239) and amended by section 9001of the Oil Pollution Act of 1990 (Public Law 101-380). The Energy Improvement and Extension Act of 2008 (Public Law 110-343) increased the barrel tax on petroleum from five cents per barrel to eight cents from 2009 through 2016, and to nine cents in 2017. The act also repeals the requirement that the tax be suspended when the unobligated balance exceeds $2.7 billion.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 639, 801, 757], \"page_id\": 107}], \"content\": \"Amounts equivalent to the taxes received from the environmental tax on petroleum, but only to the extent of the Oil Spill Liability Trust Fund rate, are appropriated to the fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 759, 801, 823], \"page_id\": 107}], \"content\": \"Certain amounts were transferred from other funds and were appropriated to the Oil Spill Liability Trust Fund as\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 269, 1490, 361], \"page_id\": 107}], \"content\": \"provided by 26 United States Code 9509(b). Certain paid penalties and amounts recovered for damages are also appropriated to the fund.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 361, 1492, 481], \"page_id\": 107}], \"content\": \"Amounts in the fund are available for oil spill cleanup costs and certain other related purposes as provided by appropriations acts or section 6002(b) of the Oil Pollution Act of 1990 (Public Law 101-380).\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 483, 1492, 606], \"page_id\": 107}], \"content\": \"When the provisions of 26 United States Code 9602(b) are met, amounts available in the fund exceeding outlay requirements are invested in public debt securities. Interest is credited to the fund.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 606, 1490, 759], \"page_id\": 107}], \"content\": \"Annual reports to Congress, required by 26 United States Code 9602(a), are submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and results of operations of the fund during the past fiscal year and those expected during the next 5 fiscal years.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1989, 260, 2018], \"page_id\": 107}], \"content\": \"March 2014\", \"description\": null, \"id\": 10, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [723, 97, 918, 127], \"page_id\": 108}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1443, 99, 1497, 127], \"page_id\": 108}], \"content\": \"105\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [497, 243, 1144, 314], \"page_id\": 108}], \"content\": \"